import { createRoute, z } from '@hono/zod-openapi'

const MetadataSchema = z
  .record(z.string(), z.string())
  .openapi({
    description:
      'Set of key-value pairs.\nMetadata can be used to store additional information about a resource.',
    example: { externalId: '019142cc-a016-796a-8113-1a942fecd26d' },
    'x-go-type': 'map[string]string',
  })
  .openapi('Metadata')

const AppTypeSchema = z
  .enum(['stripe', 'sandbox', 'custom_invoicing'])
  .openapi({ description: 'Type of the app.' })
  .openapi('AppType')

const AppCapabilityTypeSchema = z
  .enum(['reportUsage', 'reportEvents', 'calculateTax', 'invoiceCustomers', 'collectPayments'])
  .openapi({ description: 'App capability type.' })
  .openapi('AppCapabilityType')

const AppCapabilitySchema = z
  .object({
    type: AppCapabilityTypeSchema.openapi({ description: 'The capability type.' }),
    key: z
      .string()
      .regex(/^[a-z0-9]+(?:_[a-z0-9]+)*$/)
      .min(1)
      .max(64)
      .openapi({ description: 'Key' }),
    name: z.string().openapi({ description: 'The capability name.' }),
    description: z.string().openapi({ description: 'The capability description.' }),
  })
  .openapi({
    required: ['type', 'key', 'name', 'description'],
    description:
      "App capability.\n\nCapabilities only exist in config so they don't extend the Resource model.",
    example: {
      type: 'collectPayments',
      key: 'stripe_collect_payment',
      name: 'Collect Payments',
      description:
        "Stripe payments collects outstanding revenue with Stripe customer's default payment method.",
    },
  })
  .openapi('AppCapability')

const InstallMethodSchema = z
  .enum(['with_oauth2', 'with_api_key', 'no_credentials_required'])
  .openapi({ description: 'Install method of the application.' })
  .openapi('InstallMethod')

const MarketplaceListingSchema = z
  .object({
    type: AppTypeSchema.openapi({ description: "The app's type" }),
    name: z.string().openapi({ description: "The app's name." }),
    description: z.string().openapi({ description: "The app's description." }),
    capabilities: z.array(AppCapabilitySchema).openapi({ description: "The app's capabilities." }),
    installMethods: z
      .array(InstallMethodSchema)
      .openapi({ description: 'Install methods.\n\nList of methods to install the app.' }),
  })
  .openapi({
    required: ['type', 'name', 'description', 'capabilities', 'installMethods'],
    description:
      "A marketplace listing.\nRepresent an available app in the app marketplace that can be installed to the organization.\n\nMarketplace apps only exist in config so they don't extend the Resource model.",
    example: {
      type: 'stripe',
      name: 'Stripe',
      description: 'Stripe integration allows you to collect payments with Stripe.',
      capabilities: [
        {
          type: 'calculateTax',
          key: 'stripe_calculate_tax',
          name: 'Calculate Tax',
          description: 'Stripe Tax calculates tax portion of the invoices.',
        },
        {
          type: 'invoiceCustomers',
          key: 'stripe_invoice_customers',
          name: 'Invoice Customers',
          description: 'Stripe invoices customers with due amount.',
        },
        {
          type: 'collectPayments',
          key: 'stripe_collect_payments',
          name: 'Collect Payments',
          description:
            "Stripe payments collects outstanding revenue with Stripe customer's default payment method.",
        },
      ],
      installMethods: ['with_oauth2', 'with_api_key'],
    },
  })
  .openapi('MarketplaceListing')

const AppStatusSchema = z
  .enum(['ready', 'unauthorized'])
  .openapi({ description: 'App installed status.' })
  .openapi('AppStatus')

