export const getApiV1MetersMeterIdOrSlugQueryRoute = createRoute({
  method: 'get',
  path: '/api/v1/meters/{meterIdOrSlug}/query',
  tags: ['Meters'],
  summary: 'Query meter',
  description: 'Query meter for usage.',
  operationId: 'queryMeter',
  request: {
    params: z.object({
      meterIdOrSlug: z
        .string()
        .regex(/^[a-z0-9]+(?:_[a-z0-9]+)*$|^[0-7][0-9A-HJKMNP-TV-Za-hjkmnp-tv-z]{25}$/)
        .min(1)
        .max(64)
        .openapi({
          param: {
            name: 'meterIdOrSlug',
            in: 'path',
            required: true,
            schema: {
              type: 'string',
              minLength: 1,
              maxLength: 64,
              pattern: '^[a-z0-9]+(?:_[a-z0-9]+)*$|^[0-7][0-9A-HJKMNP-TV-Za-hjkmnp-tv-z]{25}$',
            },
          },
        }),
    }),
    query: z
      .looseObject({})
      .transform((val) => {
        const rest: [string, unknown][] = []
        const groups = new Map<string, Record<string, unknown>>()
        const group = (name: string) => {
          const found = groups.get(name)
          if (found !== undefined) return found
          const made: Record<string, unknown> = Object.create(null)
          groups.set(name, made)
          return made
        }
        const isGroup = (item: unknown): item is Record<string, unknown> =>
          typeof item === 'object' && item !== null && !Array.isArray(item)
        const lists = new WeakSet<object>()
        const isIndex = (part: string | undefined) => part !== undefined && /^\d*$/.test(part)
        const child = (target: Record<string, unknown>, key: string, asList: boolean) => {
          const held = target[key]
          if (isGroup(held)) return held
          const made: Record<string, unknown> = Object.create(null)
          if (asList) lists.add(made)
          target[key] = made
          return made
        }
        const set = (
          root: Record<string, unknown>,
          path: readonly string[],
          item: unknown,
        ): void => {
          const work: [Record<string, unknown>, number, unknown, boolean][] = [
            [root, 0, item, false],
          ]
          for (let job = work.pop(); job !== undefined; job = work.pop()) {
            const [target, at, value, split] = job
            const head = path[at]
            if (head === undefined) continue
            const next = path[at + 1]
            if (head === '') {
              if (!split && Array.isArray(value)) {
                for (let i = value.length - 1; i >= 0; i -= 1)
                  work.push([target, at, value[i], true])
                continue
              }
              const size = Object.keys(target).length
              if (next === undefined) {
                target[String(size)] = value
                continue
              }
              const free =
                next === ''
                  ? -1
                  : Object.values(target).findIndex((held) => isGroup(held) && !(next in held))
              work.push([
                child(target, String(free < 0 ? size : free), isIndex(next)),
                at + 1,
                value,
                false,
              ])
              continue
            }
            if (next === undefined) {
              target[head] = value
              continue
            }
            work.push([child(target, head, isIndex(next)), at + 1, value, false])
          }
        }
        const settle = (root: unknown): unknown => {
          if (!isGroup(root)) return root
          const found: [Record<string, unknown>, string, Record<string, unknown>][] = []
          const queue: Record<string, unknown>[] = [root]
          for (const node of queue) {
            for (const [key, inner] of Object.entries(node)) {
              if (isGroup(inner)) {
                found.push([node, key, inner])
                queue.push(inner)
              }
            }
          }
          const finish = (group: Record<string, unknown>): unknown =>
            lists.has(group)
              ? Object.entries(group)
                  .sort((a, b) => Number(a[0]) - Number(b[0]))
                  .map(([, inner]) => inner)
              : Object.assign(Object.create(null), group)
          for (const [parent, key, group] of found.reverse()) {
            parent[key] = finish(group)
          }
          return finish(root)
        }
        const deep: string[] = ['filterGroupBy']
        for (const [key, item] of Object.entries(val)) {
          const match = /^([^\[\]]+)((?:\[[^\[\]]*\])+)$/.exec(key)
          const name = match?.[1]
          const path = match?.[2]
          if (name !== undefined && path !== undefined && deep.includes(name)) {
            const parts = path.slice(1, -1).split('][')
            set(group(name), parts, item)
            continue
          }
          rest.push([key, item])
        }
        return Object.fromEntries([
          ...rest,
          ...[...groups].map(([name, held]) => [name, settle(held)] as const),
        ])
      })
      .pipe(
        z.object({
          clientId: MeterQueryClientIdParamsSchema,
          from: MeterQueryFromParamsSchema,
          to: MeterQueryToParamsSchema,
          windowSize: MeterQueryWindowSizeParamsSchema,
          windowTimeZone: MeterQueryWindowTimeZoneParamsSchema,
          subject: MeterQuerySubjectParamsSchema,
          filterCustomerId: MeterQueryFilterCustomerIdParamsSchema,
          filterGroupBy: MeterQueryFilterGroupByParamsSchema,
          advancedMeterGroupByFilters: MeterQueryAdvancedMeterGroupByFiltersParamsSchema,
          groupBy: MeterQueryGroupByParamsSchema,
        }),
      ),
  },
  responses: {
    200: {
      description: 'The request has succeeded.',
      content: {
        'application/json': { schema: MeterQueryResultSchema },
        'text/csv': { schema: z.string() },
      },
    },
    400: {
      description:
        'The server cannot or will not process the request due to something that is perceived to be a client error (e.g., malformed request syntax, invalid request message framing, or deceptive request routing).',
      content: { 'application/problem+json': { schema: BadRequestProblemResponseSchema } },
    },
    401: {
      description:
        'The request has not been applied because it lacks valid authentication credentials for the target resource.',
      content: { 'application/problem+json': { schema: UnauthorizedProblemResponseSchema } },
    },
    403: {
      description: 'The server understood the request but refuses to authorize it.',
      content: { 'application/problem+json': { schema: ForbiddenProblemResponseSchema } },
    },
    404: {
      description:
        'The origin server did not find a current representation for the target resource or is not willing to disclose that one exists.',
      content: { 'application/problem+json': { schema: NotFoundProblemResponseSchema } },
    },
    412: {
      description:
        'One or more conditions given in the request header fields evaluated to false when tested on the server.',
      content: { 'application/problem+json': { schema: PreconditionFailedProblemResponseSchema } },
    },
    500: {
      description:
        'The server encountered an unexpected condition that prevented it from fulfilling the request.',
      content: { 'application/problem+json': { schema: InternalServerErrorProblemResponseSchema } },
    },
    503: {
      description:
        'The server is currently unable to handle the request due to a temporary overload or scheduled maintenance, which will likely be alleviated after some delay.',
      content: { 'application/problem+json': { schema: ServiceUnavailableProblemResponseSchema } },
    },
    default: {
      description: 'An unexpected error response.',
      content: { 'application/problem+json': { schema: UnexpectedProblemResponseSchema } },
    },
  },
})

